import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent, within } from "@testing-library/react";
import JobsOverviewCard from "../JobsOverviewCard";
import type { PastJob } from "@/pages/Index";

// Mock Supabase client
vi.mock("@/integrations/supabase/client", () => ({
  supabase: {
    from: () => ({
      select: () => ({
        in: () => Promise.resolve({ data: mockResults }),
      }),
    }),
  },
}));

let mockResults: Array<{ job_id: string; overall_score: number }> = [];

function makeJob(overrides: Partial<PastJob> & { id: string }): PastJob {
  return {
    title: "Test Job",
    job_description: "Some description",
    status: "completed",
    created_at: "2026-03-20T10:00:00Z",
    resume_count: 5,
    jd_analysis_json: null,
    dynamic_weights_json: null,
    inbox_email: null,
    ...overrides,
  };
}

describe("JobsOverviewCard", () => {
  const onSelectJob = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    mockResults = [];
  });

  // ── Rendering ──────────────────────────────────────────────────────────────

  it("renders the header and subtitle", () => {
    render(<JobsOverviewCard jobs={[]} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText("Jobs Overview")).toBeInTheDocument();
    expect(screen.getByText("Track and manage all your job postings.")).toBeInTheDocument();
  });

  it("renders column headers", () => {
    render(<JobsOverviewCard jobs={[makeJob({ id: "1" })]} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText("Job Title")).toBeInTheDocument();
    expect(screen.getByText("Resumes")).toBeInTheDocument();
    expect(screen.getByText("Avg. Match Score")).toBeInTheDocument();
    expect(screen.getByText("Status")).toBeInTheDocument();
    expect(screen.getByText("Created On")).toBeInTheDocument();
  });

  it("renders job rows with correct data", () => {
    const jobs = [
      makeJob({ id: "1", title: "Frontend Developer", resume_count: 12, status: "completed" }),
      makeJob({ id: "2", title: "UI Designer", resume_count: 3, status: "pending" }),
    ];
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);

    expect(screen.getByText("Frontend Developer")).toBeInTheDocument();
    expect(screen.getByText("UI Designer")).toBeInTheDocument();
    expect(screen.getByText("12")).toBeInTheDocument();
    expect(screen.getByText("3")).toBeInTheDocument();
  });

  it("shows 'Untitled Job' for jobs without a title", () => {
    render(<JobsOverviewCard jobs={[makeJob({ id: "1", title: null })]} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText("Untitled Job")).toBeInTheDocument();
  });

  it("formats the date correctly", () => {
    render(
      <JobsOverviewCard
        jobs={[makeJob({ id: "1", created_at: "2026-03-24T00:00:00Z" })]}
        loading={false}
        onSelectJob={onSelectJob}
      />
    );
    expect(screen.getByText("Mar 24, 2026")).toBeInTheDocument();
  });

  // ── Status Badges ─────────────────────────────────────────────────────────

  it("renders correct status badges", () => {
    const jobs = [
      makeJob({ id: "1", status: "completed" }),
      makeJob({ id: "2", status: "pending" }),
      makeJob({ id: "3", status: "failed" }),
    ];
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText("Completed")).toBeInTheDocument();
    expect(screen.getByText("Pending")).toBeInTheDocument();
    expect(screen.getByText("Failed")).toBeInTheDocument();
  });

  // ── Loading State ─────────────────────────────────────────────────────────

  it("shows skeleton rows when loading", () => {
    const { container } = render(<JobsOverviewCard jobs={[]} loading={true} onSelectJob={onSelectJob} />);
    // Skeleton rows should render (5 skeleton rows * 6 cells = 30 skeletons)
    const skeletons = container.querySelectorAll("[class*='skeleton'], [class*='Skeleton']");
    expect(skeletons.length).toBeGreaterThan(0);
  });

  // ── Empty State ───────────────────────────────────────────────────────────

  it("shows empty message when no jobs", () => {
    render(<JobsOverviewCard jobs={[]} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText("No jobs yet. Create your first job to get started.")).toBeInTheDocument();
  });

  it("shows filter-specific empty message when filters active", () => {
    render(<JobsOverviewCard jobs={[makeJob({ id: "1", status: "completed" })]} loading={false} onSelectJob={onSelectJob} />);
    // Search for something that doesn't exist
    const searchInput = screen.getByPlaceholderText("Search jobs...");
    fireEvent.change(searchInput, { target: { value: "nonexistent" } });
    expect(screen.getByText("No jobs match your filters.")).toBeInTheDocument();
  });

  // ── Search Filter ─────────────────────────────────────────────────────────

  it("filters jobs by search query", () => {
    const jobs = [
      makeJob({ id: "1", title: "Frontend Developer" }),
      makeJob({ id: "2", title: "Backend Engineer" }),
      makeJob({ id: "3", title: "UI Designer" }),
    ];
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);

    const searchInput = screen.getByPlaceholderText("Search jobs...");
    fireEvent.change(searchInput, { target: { value: "engineer" } });

    expect(screen.queryByText("Frontend Developer")).not.toBeInTheDocument();
    expect(screen.getByText("Backend Engineer")).toBeInTheDocument();
    expect(screen.queryByText("UI Designer")).not.toBeInTheDocument();
  });

  it("search is case-insensitive", () => {
    const jobs = [makeJob({ id: "1", title: "Frontend Developer" })];
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);

    fireEvent.change(screen.getByPlaceholderText("Search jobs..."), { target: { value: "FRONTEND" } });
    expect(screen.getByText("Frontend Developer")).toBeInTheDocument();
  });

  // ── Click Handler ─────────────────────────────────────────────────────────

  it("calls onSelectJob when a row is clicked", () => {
    render(<JobsOverviewCard jobs={[makeJob({ id: "job-123", title: "My Job" })]} loading={false} onSelectJob={onSelectJob} />);
    fireEvent.click(screen.getByText("My Job"));
    expect(onSelectJob).toHaveBeenCalledWith("job-123");
  });

  // ── Employment Tags ───────────────────────────────────────────────────────

  it("renders employment tags from jd_analysis_json", () => {
    const jobs = [
      makeJob({
        id: "1",
        jd_analysis_json: { employment_type: "Full Time", work_type: "Remote" },
      }),
    ];
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText("Full time · Remote")).toBeInTheDocument();
  });

  it("does not render tags when jd_analysis_json is null", () => {
    const jobs = [makeJob({ id: "1", jd_analysis_json: null })];
    const { container } = render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);
    // No tag line should exist beyond the title
    const row = container.querySelector("tr.cursor-pointer");
    const tagLine = row?.querySelectorAll("p.text-xs.text-muted-foreground");
    // Should be 0 (no tags) or the tags element shouldn't exist
    expect(tagLine?.length ?? 0).toBeLessThanOrEqual(0);
  });

  // ── Circular Score ────────────────────────────────────────────────────────

  it("shows dash for jobs with 0 resumes", () => {
    const jobs = [makeJob({ id: "1", resume_count: 0 })];
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText("—")).toBeInTheDocument();
  });

  // ── Pagination ────────────────────────────────────────────────────────────

  it("paginates when more than 10 jobs", () => {
    const jobs = Array.from({ length: 15 }, (_, i) =>
      makeJob({ id: `job-${i}`, title: `Job ${i}` })
    );
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);

    // Should show pagination info
    expect(screen.getByText(/Showing 1–10 of 15 jobs/)).toBeInTheDocument();

    // Page 2 button should exist
    const page2Btn = screen.getByRole("button", { name: "2" });
    expect(page2Btn).toBeInTheDocument();

    // Click page 2
    fireEvent.click(page2Btn);
    expect(screen.getByText(/Showing 11–15 of 15 jobs/)).toBeInTheDocument();
  });

  it("does not show pagination for fewer than 10 jobs", () => {
    const jobs = Array.from({ length: 5 }, (_, i) =>
      makeJob({ id: `job-${i}`, title: `Job ${i}` })
    );
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText(/Showing 1–5 of 5 jobs/)).toBeInTheDocument();
    // No Prev/Next buttons
    expect(screen.queryByRole("button", { name: "Prev" })).not.toBeInTheDocument();
  });

  it("resets page when search changes", () => {
    const jobs = Array.from({ length: 15 }, (_, i) =>
      makeJob({ id: `job-${i}`, title: `Job ${i}` })
    );
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);

    // Go to page 2
    fireEvent.click(screen.getByRole("button", { name: "2" }));
    expect(screen.getByText(/Showing 11–15/)).toBeInTheDocument();

    // Search resets to page 1
    fireEvent.change(screen.getByPlaceholderText("Search jobs..."), { target: { value: "Job 1" } });
    // Should reset to showing from 1
    expect(screen.queryByText(/Showing 11/)).not.toBeInTheDocument();
  });

  // ── Icon Selection ────────────────────────────────────────────────────────

  it("assigns code icon for developer jobs", () => {
    const { container } = render(
      <JobsOverviewCard
        jobs={[makeJob({ id: "1", title: "Senior Developer" })]}
        loading={false}
        onSelectJob={onSelectJob}
      />
    );
    // The icon container should have violet background (index 1 = Code2)
    const iconContainer = container.querySelector(".bg-violet-100");
    expect(iconContainer).toBeInTheDocument();
  });

  it("assigns palette icon for design jobs", () => {
    const { container } = render(
      <JobsOverviewCard
        jobs={[makeJob({ id: "1", title: "UI UX Designer" })]}
        loading={false}
        onSelectJob={onSelectJob}
      />
    );
    const iconContainer = container.querySelector(".bg-pink-100");
    expect(iconContainer).toBeInTheDocument();
  });

  // ── Job Count Display ─────────────────────────────────────────────────────

  it("shows total job count in header", () => {
    const jobs = Array.from({ length: 3 }, (_, i) =>
      makeJob({ id: `job-${i}`, title: `Job ${i}` })
    );
    render(<JobsOverviewCard jobs={jobs} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText("3 jobs")).toBeInTheDocument();
  });

  it("shows singular 'job' for 1 job", () => {
    render(<JobsOverviewCard jobs={[makeJob({ id: "1" })]} loading={false} onSelectJob={onSelectJob} />);
    expect(screen.getByText("1 job")).toBeInTheDocument();
  });
});

