267	        </div>
268	
269	        {/* Dashboard view */}
270	        {showDashboard && !selectedJobId && user ? (
271	          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
272	            {/* Hero Section — Greeting + Create Button */}
273	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
