276	                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
277	                </h1>
278	                <p className="text-sm text-muted-foreground mt-1">
279	                  Here's an overview of your hiring activity and insights.
280	                </p>
281	              </div>
282	              <Button size="lg" className="gap-2 shadow-md px-6" onClick={handleNewJob}>
283	                <Plus className="h-4 w-4" /> Create Job
284	              </Button>
285	            </div>
286	
287	            {/* Stats Cards */}
288	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
289	              {[
290	                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
291	                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
292	                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
293	                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
294	              ].map((s) => (
295	                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
296	                  <CardContent className="px-5 py-4 flex items-center gap-4">
297	                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
298	                      <s.icon className="h-5 w-5" />
299	                    </div>
300	                    <div>
301	                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
302	                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
303	                    </div>
304	                  </CardContent>
305	                </Card>
306	              ))}
