82	      (job) =>
83	        getDisplayTitle(job).toLowerCase().includes(q) ||
84	        job.job_description.toLowerCase().includes(q)
85	    );
86	  }, [pastJobs, search]);
87	
88	  useEffect(() => {
89	    if (editingId && editInputRef.current) {
90	      editInputRef.current.focus();
91	      editInputRef.current.select();
92	    }
93	  }, [editingId]);
94	
95	  const startEditing = (job: PastJob) => {
96	    setEditingId(job.id);
97	    setEditValue(getDisplayTitle(job));
98	  };
99	
100	  const saveRename = async () => {
101	    if (!editingId || !editValue.trim()) {
102	      setEditingId(null);
103	      return;
104	    }
105	    try {
106	      const { error } = await supabase
107	        .from("jobs")
