126	  };
127	
128	  return (
129	    <>
130	      <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
131	        <SidebarContent>
132	          {/* HOME section */}
133	          <SidebarGroup>
134	            <SidebarGroupLabel>Home</SidebarGroupLabel>
135	            <SidebarGroupContent>
136	              <SidebarMenu>
137	                {isAuthenticated && onDashboard && (
138	                  <SidebarMenuItem>
139	                    <SidebarMenuButton isActive={showDashboard && !selectedJobId} onClick={onDashboard}>
140	                      <Home className="h-4 w-4" />
141	                      <span>Dashboard</span>
142	                    </SidebarMenuButton>
143	                  </SidebarMenuItem>
144	                )}
145	                {isAuthenticated && onMyJobs && (
146	                  <SidebarMenuItem>
147	                    <SidebarMenuButton isActive={showMyJobs} onClick={onMyJobs}>
148	                      <Briefcase className="h-4 w-4" />
149	                      <span>My Jobs</span>
150	                    </SidebarMenuButton>
151	                  </SidebarMenuItem>
152	                )}
153	              </SidebarMenu>
154	            </SidebarGroupContent>
155	          </SidebarGroup>
156	
157	          <SidebarSeparator />
158	
159	          {/* JOBS section */}
160	          <SidebarGroup className="flex-1">
161	            <SidebarGroupLabel className="flex items-center gap-2">
162	              <span>Jobs</span>
163	              {search && <span className="ml-auto text-[11px]">({filteredJobs.length})</span>}
164	            </SidebarGroupLabel>
165	            <SidebarGroupContent className="space-y-2">
166	              {/* New Job + Search */}
167	              <div className="px-2 space-y-2">
168	                <Button
169	                  size="sm"
170	                  className="w-full gap-1.5"
171	                  onClick={() => { if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; } onNewJob(); }}
172	                >
173	                  <Plus className="h-3.5 w-3.5" /> New Job
174	                </Button>
175	                <div className="relative">
176	                  <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
177	                  <SidebarInput
178	                    placeholder="Search jobs…"
179	                    value={search}
180	                    onChange={(e) => setSearch(e.target.value)}
181	                    className="pl-8 pr-7"
182	                  />
183	                  {search && (
184	                    <button
185	                      onClick={() => setSearch("")}
186	                      className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
187	                      aria-label="Clear search"
188	                    >
189	                      <X className="h-3.5 w-3.5" />
190	                    </button>
191	                  )}
192	                </div>
193	              </div>
194	
195	              {!isAuthenticated ? (
196	                <div className="px-3 py-3">
197	                  <button
198	                    onClick={() => onAuthRequired?.()}
199	                    className="w-full rounded-lg border border-dashed border-border px-3 py-5 text-center hover:border-primary/50 hover:bg-primary/5 transition-all group"
200	                  >
201	                    <Briefcase className="h-5 w-5 text-muted-foreground group-hover:text-primary mx-auto mb-2 transition-colors" />
202	                    <p className="text-xs font-medium text-foreground mb-1">No jobs yet</p>
203	                    <p className="text-[11px] text-muted-foreground mb-3">Sign in to view your job history and ranked results</p>
204	                    <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary">
205	                      Sign in to get started →
206	                    </span>
207	                  </button>
208	                </div>
209	              ) : loadingPastJobs ? (
210	                <div className="space-y-1.5 px-2">
211	                  {[0, 1, 2].map((i) => (
212	                    <div key={i} className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2" style={{ animationDelay: `${i * 80}ms`, animationFillMode: "backwards" }}>
213	                      <Skeleton className="h-4 w-3/4 bg-sidebar-accent" />
214	                      <div className="flex items-center justify-between">
215	                        <Skeleton className="h-3 w-20 bg-sidebar-accent" />
216	                        <Skeleton className="h-3 w-24 bg-sidebar-accent" />
217	                      </div>
218	                    </div>
219	                  ))}
220	                </div>
221	              ) : filteredJobs.length === 0 ? (
222	                <p className="text-sm text-muted-foreground px-4 py-6 text-center">
223	                  {search ? "No matching jobs found." : "No jobs yet. Create your first one!"}
224	                </p>
225	              ) : (
226	                <SidebarMenu className="space-y-1.5 px-2">
227	                  {filteredJobs.map((job, i) => (
228	                    <SidebarMenuItem key={job.id} className="animate-in fade-in slide-in-from-left-2 duration-200" style={{ animationDelay: `${i * 40}ms`, animationFillMode: "backwards" }}>
229	                      {editingId === job.id ? (
230	                        <div className="mx-0 rounded-lg border border-primary/50 bg-card shadow-sm px-3 py-2">
231	                          <Input
232	                            ref={editInputRef}
233	                            value={editValue}
234	                            onChange={(e) => setEditValue(e.target.value)}
235	                            onKeyDown={(e) => {
236	                              if (e.key === "Enter") saveRename();
237	                              if (e.key === "Escape") cancelEditing();
238	                            }}
239	                            onBlur={saveRename}
240	                            className="h-7 text-sm"
241	                          />
242	                        </div>
243	                      ) : (
244	                        <SidebarMenuButton
245	                          isActive={selectedJobId === job.id}
246	                          onClick={() => onSelectJob(job.id)}
247	                          className={cn(
248	                            "flex flex-col items-start gap-1 h-auto py-2.5 px-3 group/item",
249	                            "rounded-lg border transition-colors",
250	                            selectedJobId === job.id
251	                              ? "border-l-2 border-l-primary bg-sidebar-accent"
252	                              : "border-transparent hover:bg-sidebar-accent/50"
253	                          )}
254	                        >
255	                          <div className="flex items-center gap-1 w-full">
256	                            <span className="text-sm leading-snug line-clamp-2 flex-1" title={getDisplayTitle(job)}>
257	                              {getDisplayTitle(job)}
258	                            </span>
259	                            <DropdownMenu>
260	                              <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
261	                                <button className="opacity-0 group-hover/item:opacity-100 transition-opacity p-1.5 rounded hover:bg-accent shrink-0" aria-label="Job actions">
262	                                  <MoreHorizontal className="h-4 w-4 text-muted-foreground" />
263	                                </button>
264	                              </DropdownMenuTrigger>
265	                              <DropdownMenuContent align="end" className="w-36">
266	                                <DropdownMenuItem onClick={(e) => { e.stopPropagation(); startEditing(job); }}>
267	                                  <Pencil className="h-3.5 w-3.5 mr-2" />
268	                                  Rename
269	                                </DropdownMenuItem>
270	                                <DropdownMenuItem
271	                                  onClick={(e) => { e.stopPropagation(); setDeleteJobId(job.id); }}
272	                                  className="text-destructive focus:text-destructive"
273	                                >
274	                                  <Trash2 className="h-3.5 w-3.5 mr-2" />
275	                                  Delete
276	                                </DropdownMenuItem>
277	                              </DropdownMenuContent>
278	                            </DropdownMenu>
279	                          </div>
