          <SidebarTrigger />
          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
        </div>

        {/* Dashboard view */}
        {view === "dashboard" && user ? (
          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
            {/* Hero Section — Greeting + Create Button */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div>
                <h1 className="text-2xl font-bold text-foreground">
                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                  Here's an overview of your hiring activity and insights.
