        const countMap: Record<string, number> = {};
        counts?.forEach((r) => { countMap[r.job_id] = (countMap[r.job_id] || 0) + 1; });

        setPastJobs(jobs.map((j) => ({
          ...j,
          resume_count: countMap[j.id] || 0,
          inbox_email: j.inbox_email ?? null,
        })));
      } else {
