              <>
                {/* Wallet */}
                <WalletDropdown />

                {/* Notifications */}
                <NotificationBell />

                {/* Profile dropdown */}
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button className="h-9 w-9 rounded-lg bg-primary text-primary-foreground text-sm font-bold flex items-center justify-center hover:bg-primary/90 transition-all cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1" aria-label="Account menu">
                      {initials}
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-56 mt-1.5 p-0">
                    {/* User info header */}
                    <div className="px-4 py-3">
                      <p className="text-sm font-semibold text-foreground">{getUserName(user.email)}</p>
                      <p className="text-xs text-muted-foreground truncate">{user.email}</p>
                    </div>

                    <DropdownMenuSeparator className="m-0" />

                    {/* Theme switcher */}
                    <div className="px-4 py-2.5 flex items-center justify-between">
                      <span className="text-sm text-foreground">Theme</span>
                      <div className="flex items-center rounded-lg border border-border bg-muted/50 p-0.5">
                        <button
                          onClick={(e) => { e.preventDefault(); setTheme("light"); }}
                          className={`p-1.5 rounded-md transition-colors ${theme === "light" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                          aria-label="Light theme"
                        >
                          <Sun className="h-3.5 w-3.5" />
                        </button>
                        <button
                          onClick={(e) => { e.preventDefault(); setTheme("dark"); }}
                          className={`p-1.5 rounded-md transition-colors ${theme === "dark" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                          aria-label="Dark theme"
                        >
                          <Moon className="h-3.5 w-3.5" />
                        </button>
                        <button
                          onClick={(e) => { e.preventDefault(); setTheme("system"); }}
                          className={`p-1.5 rounded-md transition-colors ${theme === "system" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                          aria-label="System theme"
                        >
                          <Monitor className="h-3.5 w-3.5" />
                        </button>
                      </div>
                    </div>

                    <DropdownMenuSeparator className="m-0" />

                    {/* Menu items */}
                    <div className="py-1">
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/profile")}>
                        <User className="h-4 w-4 mr-2.5" />
                        Profile
                      </DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/billing")}>
                        <CreditCard className="h-4 w-4 mr-2.5" />
                        Billing & Plan
                      </DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/settings")}>
                        <Settings className="h-4 w-4 mr-2.5" />
                        Settings
                      </DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/book-demo")}>
                        <CalendarCheck className="h-4 w-4 mr-2.5" />
                        Book Demo
                      </DropdownMenuItem>
                      {isAdmin && (
                        <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/admin")}>
                          <ShieldCheck className="h-4 w-4 mr-2.5" />
                          Admin
                        </DropdownMenuItem>
                      )}
                    </div>

                    <DropdownMenuSeparator className="m-0" />

                    <div className="py-1">
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={signOut}>
                        <LogOut className="h-4 w-4 mr-2.5" />
                        Log out
                      </DropdownMenuItem>
                    </div>
                  </DropdownMenuContent>
                </DropdownMenu>
              </>
            ) : (
              <>
                <Button variant="ghost" size="sm" onClick={() => openAuth("signin")}>Sign in</Button>
                <Button size="sm" onClick={() => openAuth("signup")}>Sign up free</Button>
              </>
            )}
          </div>
        </div>
      </header>
      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
    </>
  );
};

export default AppHeader;

import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "react-router-dom";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Database, ChevronDown, AlertTriangle, Plus, Zap, Gift, CreditCard } from "lucide-react";
import { useState } from "react";

const WalletDropdown = () => {
  const { profile } = useAuth();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);

  const subCredits = profile?.subscription_credits ?? 0;
  const topCredits = profile?.topup_credits ?? 0;
  const bonusCredits = profile?.bonus_credits ?? 0;
  const splitTotal = subCredits + topCredits + bonusCredits;
  const legacyCredits = profile?.credits ?? 0;
  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
  const isLowCredits = totalCredits < 3;
  const hasSplitCredits = splitTotal > 0;

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          className={`group inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 outline-none focus-visible:ring-2 focus-visible:ring-offset-2 border transition-all ${
            isLowCredits
              ? "border-destructive/40 text-destructive hover:border-destructive hover:bg-destructive/5 focus-visible:ring-destructive"
              : "border-border bg-muted/50 text-foreground hover:border-foreground/30 hover:bg-muted focus-visible:ring-ring"
          }`}
        >
          {isLowCredits ? (
            <AlertTriangle className="h-4 w-4 shrink-0" />
          ) : (
            <Database className="h-4 w-4 shrink-0 text-primary" />
          )}
          <span className="text-sm font-semibold tabular-nums">{totalCredits.toLocaleString()}</span>
          <span className="text-[11px] font-medium text-muted-foreground">Credits</span>
          <ChevronDown className={`h-3 w-3 text-muted-foreground transition-transform ${open ? "rotate-180" : ""}`} />
        </button>
      </PopoverTrigger>

      <PopoverContent align="end" className="w-64 p-0">
        {/* Header */}
        <div className="px-4 pt-3.5 pb-3">
          <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Credit Balance</p>
          <p className="text-2xl font-bold tabular-nums text-foreground mt-1">
            {totalCredits.toLocaleString()}
          </p>
        </div>

        {/* Breakdown */}
        {hasSplitCredits && (
          <>
            <Separator />
            <div className="px-4 py-3 space-y-2">
              <CreditRow icon={Zap} label="Subscription" value={subCredits} color="text-blue-500" />
              <CreditRow icon={CreditCard} label="Top-up" value={topCredits} color="text-emerald-500" />
              <CreditRow icon={Gift} label="Bonus" value={bonusCredits} color="text-amber-500" />
            </div>
          </>
        )}

        {/* Low credits warning */}
        {isLowCredits && (
          <>
            <Separator />
            <div className="px-4 py-2.5 bg-destructive/5">
              <p className="text-xs text-destructive font-medium">
                Running low on credits. Top up to keep ranking.
              </p>
            </div>
          </>
        )}

        {/* Actions */}
        <Separator />
        <div className="p-2">
          <Button
            size="sm"
            className="w-full gap-2"
            onClick={() => { setOpen(false); navigate("/billing"); }}
          >
            <Plus className="h-3.5 w-3.5" />
            Buy Credits
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
};

function CreditRow({
  icon: Icon,
  label,
  value,
  color,
}: {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  value: number;
  color: string;
}) {
  return (
    <div className="flex items-center justify-between">
      <div className="flex items-center gap-2">
        <Icon className={`h-3.5 w-3.5 ${color}`} />
        <span className="text-xs text-muted-foreground">{label}</span>
      </div>
      <span className="text-xs font-semibold tabular-nums text-foreground">{value.toLocaleString()}</span>
    </div>
  );
}

export default WalletDropdown;

import { useState, useEffect, useCallback } from "react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Bell, CheckCircle2, AlertCircle, FileText, Coins, Info, CheckCheck } from "lucide-react";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";

// ─── Types ──────────────────────────────────────────────────────────────────

interface Notification {
  id: string;
  type: "ranking_complete" | "ranking_failed" | "credits_low" | "credits_added" | "system";
  title: string;
  message: string;
  read: boolean;
  created_at: string;
  metadata?: Record<string, any>;
}

const ICON_MAP: Record<Notification["type"], { icon: typeof Bell; color: string; bg: string }> = {
  ranking_complete: { icon: CheckCircle2, color: "text-emerald-600", bg: "bg-emerald-100" },
  ranking_failed: { icon: AlertCircle, color: "text-destructive", bg: "bg-destructive/10" },
  credits_low: { icon: Coins, color: "text-amber-600", bg: "bg-amber-100" },
  credits_added: { icon: Coins, color: "text-blue-600", bg: "bg-blue-100" },
  system: { icon: Info, color: "text-muted-foreground", bg: "bg-muted" },
};

// ─── Component ──────────────────────────────────────────────────────────────

const NotificationBell = () => {
  const { user } = useAuth();
  const [open, setOpen] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [loading, setLoading] = useState(false);

  const unreadCount = notifications.filter((n) => !n.read).length;

  const fetchNotifications = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    try {
      const { data } = await supabase
        .from("notifications")
        .select("id, type, title, message, read, created_at, metadata")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(20);
      if (data) setNotifications(data as Notification[]);
    } catch {
      // Silently fail — notifications are non-critical
    } finally {
      setLoading(false);
    }
  }, [user]);

  // Fetch only when popover opens (real-time handles live updates)
  useEffect(() => {
    if (open) fetchNotifications();
  }, [open, fetchNotifications]);

  // Real-time subscription for new notifications
  useEffect(() => {
    if (!user) return;

    const channel = supabase
      .channel("notifications")
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "notifications",
          filter: `user_id=eq.${user.id}`,
        },
        (payload) => {
          setNotifications((prev) => [payload.new as Notification, ...prev].slice(0, 20));
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user?.id]);

  const markAsRead = async (id: string) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    );
    await supabase.from("notifications").update({ read: true }).eq("id", id);
  };

  const markAllAsRead = async () => {
    if (unreadCount === 0) return;
    const unreadIds = notifications.filter((n) => !n.read).map((n) => n.id);
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
    await supabase.from("notifications").update({ read: true }).in("id", unreadIds);
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          className="relative h-9 w-9 rounded-lg flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1"
          aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ""}`}
        >
          <Bell className="h-[18px] w-[18px]" />
          {unreadCount > 0 && (
            <span className="absolute -top-0.5 -right-0.5 flex items-center justify-center min-w-[18px] h-[18px] px-1 rounded-full bg-primary text-primary-foreground text-[10px] font-bold leading-none shadow-sm">
              {unreadCount > 99 ? "99+" : unreadCount}
            </span>
          )}
        </button>
      </PopoverTrigger>

      <PopoverContent align="end" className="w-80 p-0">
        {/* Header */}
        <div className="flex items-center justify-between px-4 pt-3.5 pb-3">
          <h3 className="text-sm font-semibold text-foreground">Notifications</h3>
          {unreadCount > 0 && (
            <button
              onClick={markAllAsRead}
              className="inline-flex items-center gap-1 text-[11px] font-medium text-primary hover:text-primary/80 transition-colors"
            >
              <CheckCheck className="h-3 w-3" />
              Mark all read
            </button>
          )}
        </div>

        <Separator />

        {/* Notification list */}
        <div className="max-h-[360px] overflow-y-auto">
          {loading && notifications.length === 0 ? (
            <div className="px-4 py-8 text-center">
              <div className="h-4 w-4 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto" />
              <p className="text-xs text-muted-foreground mt-2">Loading...</p>
            </div>
          ) : notifications.length === 0 ? (
            <div className="px-4 py-10 text-center">
              <Bell className="h-8 w-8 text-muted-foreground/30 mx-auto mb-2" />
              <p className="text-sm text-muted-foreground">No notifications yet</p>
              <p className="text-xs text-muted-foreground/70 mt-0.5">
                We'll notify you about job rankings and updates.
              </p>
            </div>
          ) : (
            notifications.map((notification) => {
              const style = ICON_MAP[notification.type] ?? ICON_MAP.system;
              const Icon = style.icon;

              return (
                <button
                  key={notification.id}
                  onClick={() => markAsRead(notification.id)}
                  className={cn(
                    "w-full text-left px-4 py-3 flex gap-3 hover:bg-muted/50 transition-colors border-b border-border last:border-0",
                    !notification.read && "bg-primary/[0.03]"
                  )}
                >
                  <div className={cn("h-8 w-8 rounded-lg flex items-center justify-center shrink-0 mt-0.5", style.bg)}>
                    <Icon className={cn("h-4 w-4", style.color)} />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-start justify-between gap-2">
                      <p className={cn("text-sm leading-tight truncate", !notification.read ? "font-semibold text-foreground" : "font-medium text-foreground/80")}>
                        {notification.title}
                      </p>
                      {!notification.read && (
                        <span className="h-2 w-2 rounded-full bg-primary shrink-0 mt-1.5" />
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground line-clamp-2 mt-0.5">
                      {notification.message}
                    </p>
                    <p className="text-[10px] text-muted-foreground/60 mt-1">
                      {formatDistanceToNow(new Date(notification.created_at), { addSuffix: true })}
                    </p>
                  </div>
                </button>
              );
            })
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
};

export default NotificationBell;

